const OWL_THING = "http://www.w3.org/2002/07/owl#Thing";
const OWL_NAMED_INDIVIDUAL = "http://www.w3.org/2002/07/owl#NamedIndividual";
const RDFS_RESOURCE = "http://www.w3.org/2000/01/rdf-schema#Resource";
const iri = (id, extra = {}) => ({ id, label: id, kind: "iri", ...extra });
const literal = (value) => ({ id: `"${value}"`, label: value, kind: "literal" });
const uri = (value) => ({ type: "uri", value });

/** 2,500 resources with a literal after every one, so the 1,000th graph node is resource 500. */
function largeGraph(resources = 2500) {
  const nodes = [];
  const edges = [];
  for (let index = 0; index < resources; index++) {
    nodes.push(iri(`urn:r${index}`, { x: index, y: 0 }));
    nodes.push(literal(`v${index}`));
    edges.push({ id: `e${index}`, source: `urn:r${index}`, predicate: `urn:p${index % 3}`, label: "p", target: `"v${index}"` });
  }
  return { nodes, edges, revision: 1 };
}

test("labels are looked up for every resource of a large graph, not only the first 1,000 nodes", () => {
  const graph = largeGraph();
  graph.nodes[0] = { ...graph.nodes[0], types: [{ id: "urn:Person", label: "Person" }] };
  const ids = labelLookupIds(graph, {});
  assert.deepEqual(ids.slice(0, 4), ["urn:p0", "urn:p1", "urn:p2", "urn:Person"], "predicates, then the types");
  for (let index = 0; index < 2500; index++) assert.ok(ids.includes(`urn:r${index}`), `urn:r${index} gets its label`);
  assert.ok(!ids.some((id) => id.startsWith('"')), "literals are not resources");
  assert.equal(new Set(ids).size, ids.length, "each id once");
});

test("lookups go to the focused node first, then drawn nodes in view, then other drawn nodes, then the rest", () => {
  const nodes = [iri("urn:hidden"), iri("urn:far", { x: 5000, y: 5000 }), literal("x"), iri("urn:near", { x: 10, y: 10 }),
    iri("urn:focused")];
  const order = lookupOrder(nodes, {
    focusedId: "urn:focused",
    drawnIds: new Set(["urn:far", "urn:near", "urn:focused"]),
    view: { left: 0, top: 0, right: 100, bottom: 100 },
  });
  assert.deepEqual(order, ["urn:focused", "urn:near", "urn:far", "urn:hidden"]);
  assert.deepEqual(lookupOrder(nodes, {}), ["urn:hidden", "urn:far", "urn:near", "urn:focused"], "graph order without priorities");
});

test("the view is the viewport's rectangle in graph coordinates", () => {
  assert.deepEqual(viewBounds({ x: -200, y: 100, k: 2 }, 1280, 780), { left: 100, top: -50, right: 740, bottom: 340 });
});

test("label lookups run chunk by chunk in order, applying each chunk, and carry on past a failed chunk", async () => {
  const seen = [];
  const applied = [];
  const ids = ["a", "b", "c", "d", "e", "f", "g"];
  const ok = await resolveInChunks(ids, async (chunk) => {
    seen.push(chunk);
    if (chunk.includes("c")) throw new Error("timed out");
  }, () => applied.push(seen.length), undefined, { first: 2, rest: 3 });
  assert.deepEqual(seen, [["a", "b"], ["c", "d", "e"], ["f", "g"]], "every id is asked for");
  assert.deepEqual(applied, [1, 2, 3], "labels are applied after each chunk");
  assert.equal(ok, false, "a failed chunk is reported");
  assert.equal(await resolveInChunks(ids, async () => {}, () => {}, undefined, { first: 2, rest: 3 }), true);
});

test("an aborted label lookup stops before the next chunk and applies nothing more", async () => {
  const controller = new AbortController();
  const seen = [];
  const applied = [];
  await resolveInChunks(["a", "b", "c", "d"], async (chunk) => {
    seen.push(chunk);
    controller.abort();
  }, () => applied.push(true), controller.signal, { first: 2, rest: 2 });
  assert.deepEqual(seen, [["a", "b"]]);
  assert.deepEqual(applied, []);
});

test("type lookups reach nodes past the first 1,000", () => {
  const nodes = Array.from({ length: 1500 }, (_, index) => iri(`urn:r${index}`, index < 1000 ? { types: [] } : {}));
  assert.deepEqual(nextTypeRound(nodes, {}, 3, () => false), ["urn:r1000", "urn:r1001", "urn:r1002"]);
});

test("a type round asks for the focused node alone, then for drawn nodes before the rest", () => {
  const nodes = [iri("urn:a"), iri("urn:typed", { types: [] }), literal("x"), iri("urn:b"), iri("urn:c"), iri("urn:focused")];
  const priority = { focusedId: "urn:focused", drawnIds: new Set(["urn:c", "urn:focused"]) };
  assert.deepEqual(nextTypeRound(nodes, priority, 40, () => false), ["urn:focused"], "the details card waits for it");
  const settled = nodes.map((node) => (node.id === "urn:focused" ? { ...node, types: [] } : node));
  assert.deepEqual(nextTypeRound(settled, priority, 2, () => false), ["urn:c", "urn:a"]);
  assert.deepEqual(nextTypeRound(settled, priority, 40, (id) => id === "urn:a"), ["urn:c", "urn:b"],
    "nodes waiting to retry a failed lookup are left for later");
});

test("type rounds grow, so a large graph takes few rounds while the first colours come quickly", () => {
  assert.deepEqual([0, 1, 2, 3, 4, 5, 6, 9].map(typeRoundSize), [40, 80, 160, 320, 640, 1280, 1280, 1280]);
});

test("a node keeps all its types, the specific ones first and generic ones like owl:Thing last", () => {
  const types = [
    { id: OWL_NAMED_INDIVIDUAL, label: "NamedIndividual" },
    { id: OWL_THING, label: "Thing" },
    ...["Zebra", "Animal", "Mammal", "Horse", "Equid", "Grazer", "Herbivore"].map((label) => ({ id: `urn:${label}`, label })),
    { id: RDFS_RESOURCE, label: "Resource" },
  ];
  assert.deepEqual(orderNodeTypes(types).map((type) => type.label), [
    "Animal", "Equid", "Grazer", "Herbivore", "Horse", "Mammal", "Zebra", "NamedIndividual", "Resource", "Thing",
  ]);
});

test("types from a lookup: every node asked for gets its list, untyped ones an empty one", () => {
  const bindings = [
    { node: uri("urn:a"), type: uri(OWL_THING) },
    { node: uri("urn:a"), type: uri("urn:Person") },
    { node: uri("urn:a"), type: uri("urn:Person") },
    { node: uri("urn:a"), type: { type: "literal", value: "not a class" } },
    { node: uri("urn:elsewhere"), type: uri("urn:Person") },
    ...Array.from({ length: 7 }, (_, index) => ({ node: uri("urn:b"), type: uri(`urn:T${index}`) })),
  ];
  const types = typesFromBindings(["urn:a", "urn:b", "urn:c"], bindings, (id) => id.slice(4));
  assert.deepEqual([...types.keys()], ["urn:a", "urn:b", "urn:c"]);
  assert.deepEqual(types.get("urn:a").map((type) => type.id), ["urn:Person", OWL_THING]);
  assert.equal(types.get("urn:b").length, 7, "more than six types are kept");
  assert.deepEqual(types.get("urn:c"), [], "no types: an empty list, which shows as \"No type\"");
});

test("the lookup keeps at most NODE_TYPE_LIMIT types of a node, the most specific ones", () => {
  const bindings = [
    { node: uri("urn:a"), type: uri(OWL_THING) },
    ...Array.from({ length: NODE_TYPE_LIMIT }, (_, index) => ({ node: uri("urn:a"), type: uri(`urn:T${String(index).padStart(2, "0")}`) })),
  ];
  const kept = typesFromBindings(["urn:a"], bindings, (id) => id).get("urn:a");
  assert.equal(kept.length, NODE_TYPE_LIMIT);
  assert.ok(!kept.some((type) => type.id === OWL_THING), "the generic type gives way");
});

test("the types query asks for at most NODE_TYPE_LIMIT types per node, generic ones last", () => {
  const query = typesQuery(["urn:a"], "default");
  assert.match(query, new RegExp(`LIMIT ${NODE_TYPE_LIMIT} }`));
  assert.match(query, /ORDER BY/);
  for (const generic of [OWL_THING, RDFS_RESOURCE, OWL_NAMED_INDIVIDUAL]) assert.ok(query.includes(`<${generic}>`));
});

test("a failed or timed-out type lookup is never stored as \"no types\" and is retried later", async () => {
  let now = 1000;
  const retries = new LookupRetries();
  const graph = { nodes: [iri("urn:a"), iri("urn:b")], edges: [], revision: 1 };
  const failed = await lookupTypes(["urn:a", "urn:b"], async () => {
    throw Object.assign(new Error("Metadata query timed out."), { status: 408 });
  }, retries, () => now);
  assert.equal(failed, null, "nothing to apply");
  assert.ok(graph.nodes.every((node) => node.types === undefined), "still unknown, so still to be looked up");
  assert.equal(retries.waiting("urn:a", now), true);
  assert.equal(nextTypeRound(graph.nodes, {}, 40, (id) => retries.waiting(id, now)).length, 0, "not hammered at once");
  assert.equal(retries.nextRetryAt(), 6000);
  now = 6000;
  assert.equal(retries.waiting("urn:a", now), false, "retried once the wait is over");
  assert.deepEqual(nextTypeRound(graph.nodes, {}, 40, (id) => retries.waiting(id, now)), ["urn:a", "urn:b"]);

  const found = await lookupTypes(["urn:a", "urn:b"], async () => new Map([["urn:a", [{ id: "urn:Person", label: "Person" }]], ["urn:b", []]]),
    retries, () => now);
  assert.equal(retries.waiting("urn:a", now), false);
  assert.equal(retries.nextRetryAt(), undefined, "a success forgets the failures");
  const typed = applyNodeTypes(graph, found);
  assert.deepEqual(typed.nodes.map((node) => node.types), [[{ id: "urn:Person", label: "Person" }], []]);
});

test("an aborted type lookup is not a failure", async () => {
  const retries = new LookupRetries();
  const controller = new AbortController();
  controller.abort();
  const result = await lookupTypes(["urn:a"], async () => {
    throw new DOMException("Request cancelled", "AbortError");
  }, retries, () => 0, controller.signal);
  assert.equal(result, null);
  assert.equal(retries.waiting("urn:a", 0), false);
});

test("retries back off from 5 seconds up to 5 minutes", () => {
  const retries = new LookupRetries();
  const waits = [];
  for (let attempt = 0; attempt < 7; attempt++) {
    retries.failed(["urn:a"], 0);
    waits.push(retries.nextRetryAt());
  }
  assert.deepEqual(waits, [5000, 15000, 45000, 135000, 300000, 300000, 300000]);
});

test("applying looked-up types leaves known types and other nodes alone", () => {
  const graph = { nodes: [iri("urn:a", { types: [{ id: "urn:Stated", label: "Stated" }] }), iri("urn:b"), literal("x")], edges: [], revision: 2 };
  const typed = applyNodeTypes(graph, new Map([["urn:a", []], ["urn:b", [{ id: "urn:T", label: "T" }]]]));
  assert.deepEqual(typed.nodes[0].types, [{ id: "urn:Stated", label: "Stated" }]);
  assert.deepEqual(typed.nodes[1].types, [{ id: "urn:T", label: "T" }]);
  assert.equal(typed.nodes[2], graph.nodes[2]);
  assert.equal(applyNodeTypes(typed, new Map([["urn:b", []]])), typed, "nothing new: the same graph");
});

test("label lookups that fail are asked again once their wait is over, without waiting for the graph to change", async () => {
  clearMetadataCache();
  let now = 1000;
  let down = true;
  const ids = Array.from({ length: 90 }, (_, index) => `urn:label-retry:${index}`);
  // One batch of the portion fails; the others answer, so the portion as a whole does not throw.
  const explorer = new RdfExplorer("urn:endpoint:label-retries", ["en"], async (query) => {
    const requested = ids.filter((id) => query.includes(`<${id}>`));
    if (down && requested.includes(ids[0])) throw new Error("endpoint rejected one batch");
    return { results: { bindings: requested.map((id) => ({ resource: uri(id), labelProperty: uri(RDFS_LABEL),
      label: { type: "literal", value: `Name ${id.split(":").at(-1)}`, "xml:lang": "en" } })) } };
  });
  const retries = new LookupRetries();
  const resolve = (chunk, signal) => explorer.resolve(chunk, signal);
  const unresolved = (chunk) => explorer.unresolved(chunk);
  try {
    assert.equal(await resolveLabels(ids, resolve, unresolved, retries, () => now, () => {}), false, "not every label came");
    assert.equal(explorer.label(ids[89]), "Name 89");
    assert.notEqual(explorer.label(ids[0]), "Name 0", "a failed lookup keeps the fallback label");
    assert.deepEqual(explorer.unresolved([ids[0]]), [ids[0]], "and is never recorded as \"no label\"");
    assert.equal(retries.waiting(ids[0], now), true, "it waits before it is asked again");
    assert.equal(retries.waiting(ids[89], now), false);
    assert.deepEqual(retries.due(now), [], "nothing is asked again at once");
    assert.equal(retries.nextRetryAt(now), 6000);

    const asked = [];
    await resolveLabels([ids[0], ids[89]], async (chunk) => asked.push(...chunk), unresolved, retries, () => now, () => {});
    assert.deepEqual(asked, [ids[89]], "a graph change meanwhile leaves the waiting ones to their retry");

    down = false;
    now = 6000;
    const due = retries.due(now);
    assert.ok(due.includes(ids[0]) && !due.includes(ids[89]), "due: the failed ones only");
    assert.equal(await resolveLabels(due, resolve, unresolved, retries, () => now, () => {}), true);
    assert.equal(explorer.label(ids[0]), "Name 0", "the retry brings the label");
    assert.equal(retries.nextRetryAt(), undefined, "a success forgets the failures");
  } finally {
    explorer.dispose();
  }
});

test("a label portion that fails as a whole waits for its retry; a cancelled one is no failure", async () => {
  const retries = new LookupRetries();
  const resolved = new Set();
  const applied = [];
  const ok = await resolveLabels(["a", "b", "c", "d", "e"], async (chunk) => {
    if (chunk.includes("c")) throw new Error("timed out");
    chunk.forEach((id) => resolved.add(id));
  }, (chunk) => chunk.filter((id) => !resolved.has(id)), retries, () => 0, () => applied.push(true), undefined, { first: 2, rest: 3 });
  assert.equal(ok, false);
  assert.deepEqual(["a", "b", "c", "d", "e"].filter((id) => retries.waiting(id, 0)), ["c", "d", "e"]);
  assert.equal(applied.length, 2, "labels are applied after each portion");

  const controller = new AbortController();
  await resolveLabels(["x"], async () => {
    controller.abort();
    throw new DOMException("Request cancelled", "AbortError");
  }, (chunk) => chunk, retries, () => 0, () => {}, controller.signal);
  assert.equal(retries.waiting("x", 0), false);
});

const RDF_TYPE = "http://www.w3.org/1999/02/22-rdf-syntax-ns#type";
const statement = (source, predicate, target) => ({ source: uri(source), predicate: uri(predicate), target: uri(target) });
const loadedGraph = (rows) =>
  withLoadedTypes(mergeTriples({ nodes: [], edges: [], revision: 0 }, bindingsToTriples(rows), false, "batch-0"));
const nodeOf = (graph, id) => graph.nodes.find((node) => node.id === id);
const typeIds = (node) => node.types.map((type) => type.id);

test("a node typed only by its loaded rdf:type statements has the rest of its types looked up, once", () => {
  const graph = loadedGraph([statement("urn:a", RDF_TYPE, "urn:Person"), statement("urn:a", "urn:knows", "urn:b")]);
  const a = nodeOf(graph, "urn:a");
  assert.deepEqual(typeIds(a), ["urn:Person"], "the loaded type shows at once");
  assert.equal(needsTypes(a, statedTypes(graph.edges)), true, "but the repository may know more");
  assert.ok(nextTypeRound(graph.nodes, {}, 40, () => false, statedTypes(graph.edges)).includes("urn:a"));

  const typed = applyNodeTypes(graph, new Map([["urn:a", [{ id: OWL_THING, label: "Thing" }, { id: "urn:Agent", label: "Agent" }]]]));
  const merged = nodeOf(typed, "urn:a");
  assert.deepEqual(typeIds(merged), ["urn:Agent", "urn:Person", OWL_THING], "loaded and looked-up types, by orderNodeTypes");
  assert.equal(needsTypes(merged, statedTypes(typed.edges)), false, "asked once, not again");
  assert.ok(!nextTypeRound(typed.nodes, {}, 40, () => false, statedTypes(typed.edges)).includes("urn:a"));
  assert.equal(withLoadedTypes(typed), typed, "the loaded type is already there");
});

test("merged types stay within NODE_TYPE_LIMIT, the most specific first, and the card says there may be more", () => {
  const graph = loadedGraph([statement("urn:a", RDF_TYPE, OWL_THING)]);
  const found = Array.from({ length: NODE_TYPE_LIMIT }, (_, index) => {
    const name = `T${String(index).padStart(2, "0")}`;
    return { id: `urn:${name}`, label: name };
  });
  const typed = applyNodeTypes(graph, new Map([["urn:a", found]]));
  const merged = nodeOf(typed, "urn:a");
  assert.deepEqual(typeIds(merged), found.map((type) => type.id), "the loaded owl:Thing gives way to specific types");
  assert.equal(nodeDetails(merged, typed.edges, new Map(typed.nodes.map((node) => [node.id, node]))).moreTypes, true);
  assert.equal(withLoadedTypes(typed), typed, "labelling the graph again (explorer.apply) keeps the cap");

  const fewer = applyNodeTypes(graph, new Map([["urn:a", [{ id: "urn:Found", label: "Found" }]]]));
  const later = withLoadedTypes(mergeTriples(fewer, bindingsToTriples([statement("urn:a", RDF_TYPE, "urn:Agent")])));
  assert.deepEqual(typeIds(nodeOf(later, "urn:a")), ["urn:Agent", "urn:Found", OWL_THING],
    "a type loaded after the lookup joins in order");
});

test("a reopened graph asks again only for nodes whose types may all be loaded statements", () => {
  const graph = loadedGraph([statement("urn:a", RDF_TYPE, "urn:Person"), statement("urn:b", RDF_TYPE, "urn:Person")]);
  const typed = applyNodeTypes(graph, new Map([["urn:a", []], ["urn:b", [{ id: "urn:Agent", label: "Agent" }]]]));
  assert.equal(needsTypes(nodeOf(typed, "urn:a"), statedTypes(typed.edges)), false);
  const prepared = prepareWorkspaceSave({
    graph: typed, transform: { x: 0, y: 0, k: 1 }, query: "CONSTRUCT WHERE { ?s ?p ?o }", endpointId: "rdf4j:repo",
    customUrl: "", namedGroups: [], selectedNodeIds: [], focusedNodeId: null, scope: "default", savedAt: null,
    provenanceBatches: [{ id: "batch-0", label: "Query", endpoint: "/workbench/graph", query: "CONSTRUCT WHERE { ?s ?p ?o }",
      tripleCount: 2, loadedAt: "2026-10-20T00:00:00.000Z", limit: null, complete: true }],
  });
  const restored = parseWorkspacePayload(prepared.raw, { repositoryReferences: true }).graph;
  const stated = statedTypes(restored.edges);
  assert.deepEqual(typeIds(nodeOf(restored, "urn:b")), ["urn:Agent", "urn:Person"]);
  assert.equal(needsTypes(nodeOf(restored, "urn:a"), stated), true, "its types may all be loaded ones: asked again");
  assert.equal(needsTypes(nodeOf(restored, "urn:b"), stated), false, "a type no loaded statement states came from a lookup");
});
